-- Isolated PostgreSQL fixture only. Canonical read columns and actual V006 JPA DDL.
CREATE TABLE catalog_users(id bigint PRIMARY KEY);
CREATE TABLE catalog_batch_revisions(batch_id uuid, revision int, PRIMARY KEY(batch_id,revision));
CREATE TABLE catalog_batch_current_revisions(batch_id uuid PRIMARY KEY, revision int);
CREATE TABLE catalog_paintings(public_id uuid PRIMARY KEY, current_batch_id uuid, current_revision int,
 catalog_status text, image_display_status text, image_asset_id uuid, title text, author_name text, category text);
CREATE TABLE catalog_media_assets(public_id uuid PRIMARY KEY, source_batch_id uuid, source_revision int,
 media_status text, relative_path text, storage_uri text, content_sha256 text);
CREATE TABLE catalog_source_records(painting_id uuid, batch_id uuid, revision int);
CREATE TABLE media_assets (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    public_id VARCHAR(64) NOT NULL UNIQUE,
    owner_user_id BIGINT REFERENCES catalog_users(id) ON DELETE RESTRICT,
    storage_key VARCHAR(1024) NOT NULL UNIQUE,
    original_filename VARCHAR(512) NOT NULL,
    mime_type VARCHAR(255), file_size BIGINT, sha256 VARCHAR(64),
    width INTEGER, height INTEGER, duration_seconds DOUBLE PRECISION,
    asset_type VARCHAR(64) NOT NULL, semantic_type VARCHAR(64) NOT NULL,
    source_type VARCHAR(64) NOT NULL, visibility VARCHAR(64) NOT NULL,
    status VARCHAR(64) NOT NULL, created_at TIMESTAMP NOT NULL,
    updated_at TIMESTAMP NOT NULL
);
CREATE INDEX idx_media_assets_owner_created ON media_assets(owner_user_id, created_at);
CREATE INDEX idx_media_assets_type_status ON media_assets(asset_type, semantic_type, status);
CREATE INDEX idx_media_assets_sha256 ON media_assets(sha256);

CREATE TABLE paintings (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    public_id VARCHAR(64) NOT NULL UNIQUE, source_key VARCHAR(1024) NOT NULL UNIQUE,
    source_sequence VARCHAR(64), image_storage_name VARCHAR(512) NOT NULL,
    title VARCHAR(512), author_name VARCHAR(255), author_birth_year VARCHAR(64),
    author_birth_place VARCHAR(512), author_school VARCHAR(255), creation_year VARCHAR(255),
    creation_dynasty_raw VARCHAR(255), creation_dynasty_normalized VARCHAR(255),
    actual_size VARCHAR(255), collection_institution VARCHAR(512), category VARCHAR(255),
    subject VARCHAR(512), painting_school VARCHAR(255), style TEXT, color TEXT,
    composition TEXT, artistic_conception TEXT, brushwork TEXT, ink_method TEXT,
    painting_material TEXT, pigment TEXT, seal TEXT, cultural_symbol TEXT,
    generated_text TEXT, music_scene_description TEXT, collection_platform VARCHAR(512),
    image_asset_id BIGINT REFERENCES media_assets(id) ON DELETE SET NULL,
    image_available BOOLEAN NOT NULL DEFAULT FALSE, visible_in_gallery BOOLEAN NOT NULL DEFAULT TRUE,
    status VARCHAR(64) NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL
);
CREATE INDEX idx_paintings_image_storage_name ON paintings(image_storage_name);
CREATE INDEX idx_paintings_gallery_status ON paintings(visible_in_gallery, status);
CREATE INDEX idx_paintings_dynasty ON paintings(creation_dynasty_normalized);
CREATE INDEX idx_paintings_category ON paintings(category);
CREATE INDEX idx_paintings_author_name ON paintings(author_name);
CREATE INDEX idx_paintings_image_asset ON paintings(image_asset_id);

-- This one-to-one ledger makes the numerical JPA compatibility IDs auditable.
-- It is populated only by the explicit local projection command.
CREATE TABLE catalog_creation_painting_projection (
    catalog_painting_id UUID PRIMARY KEY REFERENCES catalog_paintings(public_id) ON DELETE RESTRICT,
    jpa_painting_id BIGINT NOT NULL UNIQUE REFERENCES paintings(id) ON DELETE RESTRICT,
    catalog_asset_id UUID REFERENCES catalog_media_assets(public_id) ON DELETE RESTRICT,
    jpa_asset_id BIGINT UNIQUE REFERENCES media_assets(id) ON DELETE RESTRICT,
    input_batch_id UUID NOT NULL, input_revision INTEGER NOT NULL,
    projected_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
    FOREIGN KEY (input_batch_id, input_revision)
      REFERENCES catalog_batch_revisions(batch_id, revision) ON DELETE RESTRICT
);
